// Plausibilitaetspruefung: Netto + USt muss Brutto ergeben (1 Cent Toleranz
// wegen kaufmaennischer Rundung). Faengt die typischen KI-Lesefehler ab,
// bevor falsche Zahlen in der Buchhaltung landen.
const raus = [];
for (const eintrag of $input.all()) {
  const r = eintrag.json.message?.content ?? eintrag.json;
  const netto = Number(r.netto ?? 0);
  const ust = Number(r.ust_betrag ?? 0);
  const brutto = Number(r.brutto ?? 0);
  const abweichung = Math.abs(netto + ust - brutto);
  raus.push({
    json: {
      ...r,
      betrag_plausibel: abweichung <= 0.01,
      abweichung_eur: Number(abweichung.toFixed(2)),
      pflichtfelder_vollstaendig: Boolean(r.lieferant && r.rechnungsnummer && r.rechnungsdatum),
      erfasst_am: new Date().toISOString().slice(0, 10),
    },
  });
}
return raus;
